{!REQUIRESCRIPT("/soap/ajax/26.0/connection.js")} 
{!REQUIRESCRIPT("/soap/ajax/26.0/apex.js")} 
//alert('Opportunity.OwnerId=='+Opportunity.OwnerId);

var user = sforce.connection.query("Select Country,isActive from User where Id = '{!Opportunity.OwnerId}' ");
var opps = sforce.connection.query("Select Amount,Total_Sales_Billing_Estimate__c from Opportunity where Id = '{!Opportunity.Id}' "); 
var records1 = user.getArray('records'); 
var countryvar = ''; 
if(opps.records.Amount >= 25000 &&
 opps.records.Total_Sales_Billing_Estimate__c <=0 &&
 (opps.records.Type === 'New Deal' || opps.records.Type === 'Up-Sell/Lift')
 ){ 
 alert("Please add sales Billing Forecast record");

 }else{
for(var i=0;i<records1.length;i++){ 
countryvar = records1[i].Country; 
} 
if(countryvar == 'United Kingdom' || countryvar == 'Ireland'){
if ( "{!Opportunity.Type}" === "Renewal" ) 
{ 
window.location.href="/apex/renewalOppWizard_step1?oppId={!Opportunity.Id}&accId={!Opportunity.AccountId}&imga={!Opportunity.IMGA_Name__c}";

//alert("Renewal Opportunities cannot go through NCSP process.");  
} 
else if( user.records.IsActive == 'false' ) 
{ 
alert('Only opportunities with active users may use the NCSP wizard'); 
} 
else 
{ 
if('{!Opportunity.StageName}' === '5 - Signed/PO in' ) 
{ 
window.location.href="/apex/NCSPWizard_Step1?oppId={!Opportunity.Id}"; 
}else 
{ 
alert("OPPORTUNITY MUST BE AT Stage '5 – Signed/PO In' BEFORE SUBMITTING TO NEW CUSTOMER IMPLEMENTATIONS TEAM"); 
} 
}
}else{
alert("The NCSP functionality is only available to IME users based in UK and Ireland. Please continue to use the 'Account Set up' button.");
}
}
